/// Enlightenment (colorless EVENT-rarity Skill, Cost 0, Self, EXHAUST).
/// C# `Enlightenment.OnPlay` (fresh DLL, F6 step32 authority): for every
/// card in hand, `EnergyCost.SetThisTurnOrUntilPlayed(1, reduceOnly: true)`,
/// or `SetThisCombat(1, reduceOnly: true)` when upgraded: an ordered
/// Absolute local modifier `min(cost, 1)` over the card's base. X-cost and
/// unplayable (negative) costs ignore it.
///
/// The engine keeps one collapsed `cost`, so the cap is written into it and
/// recorded on the existing paths for an Absolute modifier:
/// * `CostAbsolutelySet` marks the cap as owning the evaluated cost, so an
///   in-combat upgrade that lowers the base clamps it the way C#
///   `CardEnergyCost.UpgradeBy` clamps absolute modifiers (a capped
///   Barricade upgraded stays at 1, not 0);
/// * the base form's lifetime, `EndOfTurn | WhenPlayed`, is the one Snecko
///   Oil's `SetThisTurnOrUntilPlayed` roll already has: the shave is banked
///   in `SneckoCostDeltaThisTurn`, which the after-play cleanup and the
///   turn-end cleanup undo (a played Perfected Strike reaches the discard at
///   2, a held Bludgeon is back at 3 after the turn: F6
///   `enlightenment-until-played`). The upgraded form lasts the combat (no
///   bank).
///
/// Not modelled (the item's remaining ordered-ownership gaps): a cap that
/// does not bind when applied but would after another modifier expires (the
/// upgraded form's latent cap over a Stomp shaved below 1), and the
/// upgrade-clamp flag after a Snecko/base-cap expiry on a card that also
/// holds an upgraded cap. Those need an ordered per-card modifier list.
pub(crate) fn play_enlightenment(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let this_turn_only = !current_upgraded(state);
    let hand_uids: SmallVec<[CardUid; 16]> = state.player.hand.iter().copied().collect();
    for uid in hand_uids {
        let idx = uid.0.get() as usize - 1;
        if let Some(card) = state.cards.get_mut(idx) {
            if card.is_x_cost() {
                continue;
            }
            if card.cost > ENLIGHTENMENT_COST_CAP {
                let delta = i32::from(ENLIGHTENMENT_COST_CAP) - i32::from(card.cost);
                card.cost = ENLIGHTENMENT_COST_CAP;
                card.set_combat_var(VarKey::CostAbsolutelySet, 1);
                if this_turn_only {
                    let banked = card.combat_var(VarKey::SneckoCostDeltaThisTurn);
                    card.set_combat_var(VarKey::SneckoCostDeltaThisTurn, banked + delta);
                }
            }
        }
    }
    EffectResult::Resolved
}
